/**
 * Wire types mirroring the Rust domain models.
 *
 * These are generated by hand from `src-tauri/src/domain/*` — the field names are
 * identical because both sides use camelCase on the wire.
 */

export type CapabilityStatus =
  | "supported"
  | "unsupported"
  | "permission-denied"
  | "login-required"
  | "not-tested"
  | "temporarily-unavailable";

export type CanvasSessionState =
  | "not-connected"
  | "login-required"
  | "logging-in"
  | "web-authenticated"
  | "data-access-verified"
  | "session-expired"
  | "unsupported"
  | "error";

export type IndexStatus =
  | "pending"
  | "queued"
  | "processing"
  | "indexed"
  | "partial"
  | "failed"
  | "skipped";

export type MaterialKind =
  | "pdf"
  | "pptx"
  | "docx"
  | "text"
  | "markdown"
  | "image"
  | "ics"
  | "csv"
  | "json"
  | "zip"
  | "other";

export type SourceKind = "canvas" | "manual" | "import" | "ai";

