/* ------------------------------------------------------------------ */
/* Canvas course files                                                 */
/* ------------------------------------------------------------------ */

/** One file listed by Canvas and its local download state. */
export interface CanvasFile {
  id: string;
  courseId: string;
  canvasFileId: string;
  displayName: string;
  contentType: string | null;
  byteSize: number | null;
  state: "pending" | "downloading" | "downloaded" | "failed" | "unsupported";
  materialId: string | null;
  error: string | null;
  remoteUpdatedAt: string | null;
  /** Canvas folder path; null = course root. */
  folderPath: string | null;
  updatedAt: string;
}

/** Files tab payload: one entry per course. */
export interface CourseFileGroup {
  courseId: string;
  courseName: string;
  downloaded: Material[];
  pending: CanvasFile[];
  /** material id -> Canvas folder path (null = course root). */
  folderByMaterial: Record<string, string | null>;
}

export interface DownloadReport {
  downloaded: number;
  failed: number;
  skipped: number;
  errors: string[];
}

export interface CanvasDownloadEvent {
  name: string;
  state: "downloaded" | "batch-done";
  downloaded: number | null;
  failed: number | null;
  errors: string[] | null;
}